 function drawChar(x,y,type,dir,anim=0,flash=false){const px=Math.round(x*T-cam.x),py=Math.round(y*T-cam.y);if(type==='enemy'){ctx.fillStyle='#263b34';ctx.fillRect(px-5,py-2,10,3);ctx.fillStyle='#983f37';ctx.fillRect(px-5,py-8,10,8);ctx.fillStyle='#d1a96e';ctx.fillRect(px-3,py-13,6,6);ctx.fillStyle='#43372f';ctx.fillRect(px-4,py-14,8,3);ctx.fillStyle='#f0d7a2';ctx.fillRect(px+1,py-11,1,1);if(type==='enemy'&&enemies.find(e=>e.x===x&&e.y===y)?.hp===1){ctx.fillStyle='#e1b75c';ctx.fillRect(px-3,py-17,6,2)}return}if(type==='npc'){ctx.fillStyle='#293a34';ctx.fillRect(px-5,py-2,10,3);ctx.fillStyle='#547d78';ctx.fillRect(px-4,py-9,8,8);ctx.fillStyle='#d7ad78';ctx.fillRect(px-3,py-14,6,6);ctx.fillStyle='#473e33';ctx.fillRect(px-4,py-15,8,3);return}if(flash&&frame%5<3)return;ctx.fillStyle='#26372f';ctx.fillRect(px-5,py-2,10,3);const bob=Math.sin(anim*2)*1.3;ctx.fillStyle='#c1a454';ctx.fillRect(px-5,py-10+bob,10,8);ctx.fillStyle='#e8bd80';ctx.fillRect(px-4,py-15+bob,8,7);ctx.fillStyle='#76513a';ctx.fillRect(px-4,py-16+bob,8,3);ctx.fillStyle='#423b31';if(dir==='left')ctx.fillRect(px-4,py-12+bob,2,2);else if(dir==='right')ctx.fillRect(px+2,py-12+bob,2,2);else ctx.fillRect(px+2,py-12+bob,1,1);ctx.fillStyle='#5e493a';ctx.fillRect(px-4,py-3+bob,3,4);ctx.fillRect(px+1,py-3+bob,3,4);if(player.attack>0){const[dx,dy]=faceVector(player.dir);ctx.strokeStyle='#f1e4be';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(px+dx*8,py-9+dy*8);ctx.lineTo(px+dx*17-dy*5,py-9+dy*17+dx*5);ctx.stroke();ctx.fillStyle='#d5b75f';ctx.fillRect(px+dx*14-1,py-10+dy*14,3,3)}}
